const body = $input.item.json.body || $input.item.json;
const text = body.text || '';

// Extraer números (enteros y decimales, positivos y negativos)
const regex = /-?\d+(\.\d+)?/g;
const matches = text.match(regex);

if (!matches || matches.length === 0) {
  return {
    json: {
      error: 'No se encontraron números en el texto proporcionado.'
    }
  };
}

// Convertir a numérico real
const numbers = matches.map(Number);

// Calcular máximo
const maximo = Math.max(...numbers);

// Ordenar descendente
const lista_desc = [...numbers].sort((a, b) => b - a);

// Ordenar ascendente
const lista_asc = [...numbers].sort((a, b) => a - b);

// IMPORTANTE: Devolver el objeto directamente para que responseMode: "lastNode" lo envíe limpio
return {
  json: {
    maximo: maximo,
    lista_desc: lista_desc,
    lista_asc: lista_asc
  }
};
